(function(){'use strict';var _pending={};function init(){document.querySelectorAll('.mw-media-dropzone').forEach(initDropzone);if(window.MwPhotoQueue){MwPhotoQueue.on('mwPhotoUploaded',onUploaded);MwPhotoQueue.on('mwPhotoFailed',onFailed);MwPhotoQueue.on('mwPhotoRetrying',onRetrying)}}
function initDropzone(zone){var fileInput=zone.querySelector('.mw-dropzone-input');var cameraInput=zone.querySelector('.mw-dropzone-camera-input');var browseBtn=zone.querySelector('.mw-dropzone-browse');var cameraBtn=zone.querySelector('.mw-dropzone-camera');var queue=zone.querySelector('.mw-dropzone-queue');var gpsToggle=zone.querySelector('.mw-dropzone-gps-toggle');var powToggle=zone.querySelector('.mw-dropzone-pow-toggle');var config={contextType:zone.dataset.contextType||'marketing_general',contextId:zone.dataset.contextId||'0',category:zone.dataset.category||'',visibility:zone.dataset.visibility||'internal',csrf:zone.dataset.csrf||'',uploadUrl:zone.dataset.uploadUrl||'/crm/api/media-upload.php',maxSize:parseInt(zone.dataset.maxSize||'15728640',10),allowedTypes:(zone.dataset.allowedTypes||'image/jpeg,image/png,image/webp').split(',')};var stats={total:0,succeeded:0,failed:0,active:0};var cachedGps=null;var gpsRequested=!1;function requestGps(){if(gpsRequested||!navigator.geolocation)return;gpsRequested=!0;navigator.geolocation.getCurrentPosition(function(pos){cachedGps={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy}},function(){cachedGps=null},{enableHighAccuracy:!0,timeout:10000,maximumAge:60000})}
if(gpsToggle&&gpsToggle.checked)requestGps();if(gpsToggle){gpsToggle.addEventListener('change',function(){if(this.checked)requestGps();else cachedGps=null})}['dragenter','dragover'].forEach(function(evt){zone.addEventListener(evt,function(e){e.preventDefault();e.stopPropagation();zone.classList.add('mw-dropzone-active')})});['dragleave','drop'].forEach(function(evt){zone.addEventListener(evt,function(e){e.preventDefault();e.stopPropagation();zone.classList.remove('mw-dropzone-active')})});zone.addEventListener('drop',function(e){if(e.dataTransfer&&e.dataTransfer.files)handleFiles(e.dataTransfer.files);});if(browseBtn&&fileInput){browseBtn.addEventListener('click',function(e){e.preventDefault();fileInput.click()});fileInput.addEventListener('change',function(){if(this.files&&this.files.length){handleFiles(this.files);this.value=''}})}
if(cameraBtn&&cameraInput){cameraBtn.addEventListener('click',function(e){e.preventDefault();cameraInput.click()});cameraInput.addEventListener('change',function(){if(this.files&&this.files.length){handleFiles(this.files);this.value=''}})}
function isImageBlurry(file,threshold){threshold=threshold||80;return new Promise(function(resolve){if(!file.type.match(/^image\/(jpeg|png|webp)$/)){resolve(!1);return}
var url=URL.createObjectURL(file);var img=new Image();img.onload=function(){try{var c=document.createElement('canvas');c.width=100;c.height=100;var ctx=c.getContext('2d');ctx.drawImage(img,0,0,100,100);URL.revokeObjectURL(url);var data=ctx.getImageData(0,0,100,100).data;var grey=[];for(var i=0;i<data.length;i+=4){grey.push(0.299*data[i]+0.587*data[i+1]+0.114*data[i+2])}
var mean=grey.reduce(function(a,b){return a+b},0)/grey.length;var variance=grey.reduce(function(s,v){return s+(v-mean)*(v-mean)},0)/grey.length;resolve(variance<threshold)}catch(e){resolve(!1)}};img.onerror=function(){URL.revokeObjectURL(url);resolve(!1)};img.src=url})}
function handleFiles(fileList){Array.prototype.slice.call(fileList).forEach(function(file){if(config.allowedTypes.indexOf(file.type)===-1){showError(queue,file.name,'Invalid file type: '+file.type);return}
if(file.size>config.maxSize){showError(queue,file.name,'Too large (max '+Math.round(config.maxSize/1048576)+' MB)');return}
if(config.contextType==='expense'){isImageBlurry(file).then(function(blurry){if(blurry&&!window.confirm('This photo looks blurry or dark.\nUpload anyway, or retake?'))return;processFile(file)})}else{processFile(file)}})}
function processFile(file){var item=createPhotoCard(file.name,file.size,null);queue.appendChild(item);stats.total++;stats.active++;var previewBlobUrl=null;requestAnimationFrame(function(){setTimeout(function(){generatePreview(file).then(function(url){previewBlobUrl=url;var thumbEl=item.querySelector('.mw-upload-thumb');if(thumbEl&&url){var img=document.createElement('img');img.alt='';img.decoding='async';img.src=url;thumbEl.appendChild(img)}})},50)});var meta={contextType:config.contextType,contextId:config.contextId,category:config.category,visibility:config.visibility,csrf:config.csrf,uploadUrl:config.uploadUrl,powStamp:(powToggle&&powToggle.checked)?'1':'',gpsLat:(gpsToggle&&gpsToggle.checked&&cachedGps)?cachedGps.lat:null,gpsLng:(gpsToggle&&gpsToggle.checked&&cachedGps)?cachedGps.lng:null,gpsAccuracy:(gpsToggle&&gpsToggle.checked&&cachedGps)?cachedGps.accuracy:null};compressForUpload(file).then(function(uploadFile){if(window.MwPhotoQueue){MwPhotoQueue.saveAndEnqueue(uploadFile,meta).then(function(queueId){_pending[queueId]={item:item,blobUrl:previewBlobUrl,zone:zone,filename:file.name,stats:stats};item.dataset.mwQueueId=queueId}).catch(function(){setCardState(item,'error','Storage unavailable');stats.active--;stats.failed++;checkAllComplete(zone,stats)})}else{inlineUpload(uploadFile,meta,item,previewBlobUrl,stats,zone,config)}})}
zone._mwConfig=config;zone._mwQueue=queue;zone._mwStats=stats;restorePendingCards(zone,queue,config,stats)}
function restorePendingCards(zone,queue,config,stats){if(!window.MwPhotoQueue)return;MwPhotoQueue.getPendingForContext(config.contextType,config.contextId).then(function(items){if(!items.length)return;items.forEach(function(item){if(_pending[item.queueId])return;var card=createPhotoCard(item.filename,item.fileSize,item.blobUrl);if(item.status==='failed'&&item.retries>=5){setCardState(card,'error','Failed — tap to retry');var thumbEl=card.querySelector('.mw-upload-thumb');if(thumbEl){thumbEl.style.cursor='pointer';thumbEl.title='Tap to retry';thumbEl.addEventListener('click',function retryClick(){thumbEl.removeEventListener('click',retryClick);thumbEl.style.cursor='';thumbEl.title='';setCardState(card,'uploading','Retrying…');MwPhotoQueue.processQueue()},{once:!0})}}else{setCardState(card,'uploading',item.status==='failed'?'Retrying…':'Syncing…')}
card.dataset.mwQueueId=item.queueId;queue.appendChild(card);stats.active++;stats.total++;_pending[item.queueId]={item:card,blobUrl:item.blobUrl,zone:zone,filename:item.filename,stats:stats}})}).catch(function(){})}
function onUploaded(detail){var entry=_pending[detail.queueId];if(!entry)return;var item=entry.item;setCardState(item,'done',detail.isDuplicate?'Linked':'Saved');if(detail.thumbUrl){var thumbEl=item.querySelector('.mw-upload-thumb');var img=thumbEl?thumbEl.querySelector('img'):null;if(img){var newImg=new Image();newImg.onload=function(){img.src=detail.thumbUrl;URL.revokeObjectURL(entry.blobUrl)};newImg.onerror=function(){URL.revokeObjectURL(entry.blobUrl)};newImg.src=detail.thumbUrl}}else{URL.revokeObjectURL(entry.blobUrl)}
entry.stats.active--;entry.stats.succeeded++;entry.zone.dispatchEvent(new CustomEvent('mediaUploaded',{detail:{media_id:detail.mediaId,uuid:detail.uuid,thumb_url:detail.thumbUrl,is_duplicate:detail.isDuplicate,filename:entry.filename}}));checkAllComplete(entry.zone,entry.stats);delete _pending[detail.queueId]}
function onFailed(detail){var entry=_pending[detail.queueId];if(!entry)return;var item=entry.item;setCardState(item,'error','Failed — tap to retry');var thumbEl=item.querySelector('.mw-upload-thumb');if(thumbEl){thumbEl.style.cursor='pointer';thumbEl.title='Tap to retry';thumbEl.addEventListener('click',function retryClick(){thumbEl.removeEventListener('click',retryClick);thumbEl.style.cursor='';thumbEl.title='';setCardState(item,'uploading','Retrying…');if(window.MwPhotoQueue){MwPhotoQueue.processQueue()}},{once:!0})}
entry.stats.active--;entry.stats.failed++;entry.zone.dispatchEvent(new CustomEvent('mediaError',{detail:{filename:entry.filename,errors:[detail.error||'Upload failed']}}));checkAllComplete(entry.zone,entry.stats);delete _pending[detail.queueId]}
function onRetrying(detail){var entry=_pending[detail.queueId];if(!entry)return;setCardState(entry.item,'uploading','Retrying ('+detail.attempt+')…')}
function checkAllComplete(zone,stats){if(stats.active<=0){zone.dispatchEvent(new CustomEvent('allUploadsComplete',{detail:{total:stats.total,succeeded:stats.succeeded,failed:stats.failed}}));stats.total=0;stats.succeeded=0;stats.failed=0;stats.active=0}}
function createPhotoCard(filename,fileSize,blobUrl){var div=document.createElement('div');div.className='mw-upload-item mw-upload-item--photo';var sizeStr=fileSize>1048576?(fileSize/1048576).toFixed(1)+' MB':Math.round(fileSize/1024)+' KB';var thumbImg=blobUrl?'<img src="'+escapeAttr(blobUrl)+'" alt="" loading="eager">':'';div.innerHTML='<span class="mw-upload-thumb mw-thumb-uploading">'+thumbImg+'</span>'+'<span class="mw-upload-meta">'+'<span class="mw-upload-name" title="'+escapeAttr(filename)+'">'+escapeHtml(filename)+'</span>'+'<span class="mw-upload-size">'+sizeStr+'</span>'+'<span class="mw-upload-status">Uploading…</span>'+'</span>';return div}
function setCardState(item,state,statusText){var thumbEl=item.querySelector('.mw-upload-thumb');var statusEl=item.querySelector('.mw-upload-status');if(thumbEl){thumbEl.classList.remove('mw-thumb-uploading','mw-thumb-done','mw-thumb-error')}
item.classList.remove('mw-upload-done','mw-upload-error');if(state==='done'){if(thumbEl)thumbEl.classList.add('mw-thumb-done');item.classList.add('mw-upload-done')}else if(state==='error'){if(thumbEl)thumbEl.classList.add('mw-thumb-error');item.classList.add('mw-upload-error')}else{if(thumbEl)thumbEl.classList.add('mw-thumb-uploading');}
if(statusEl)statusEl.textContent=statusText||''}
function showError(queueEl,name,msg){var div=document.createElement('div');div.className='mw-upload-item mw-upload-error';div.innerHTML='<span class="mw-upload-thumb mw-thumb-error"></span>'+'<span class="mw-upload-meta">'+'<span class="mw-upload-name">'+escapeHtml(name)+'</span>'+'<span class="mw-upload-size"></span>'+'<span class="mw-upload-status">'+escapeHtml(msg)+'</span>'+'</span>';queueEl.appendChild(div)}
function inlineUpload(file,meta,item,blobUrl,stats,zone){var formData=new FormData();formData.append('files[]',file);formData.append('csrf_token',meta.csrf||'');formData.append('context_type',meta.contextType||'');formData.append('context_id',String(meta.contextId||''));formData.append('category',meta.category||'');formData.append('visibility',meta.visibility||'internal');if(meta.powStamp)formData.append('pow_stamp',meta.powStamp);if(meta.gpsLat)formData.append('gps_lat',String(meta.gpsLat));if(meta.gpsLng)formData.append('gps_lng',String(meta.gpsLng));if(meta.gpsAccuracy)formData.append('gps_accuracy',String(meta.gpsAccuracy));fetch(meta.uploadUrl||'/crm/api/media-upload.php',{method:'POST',body:formData}).then(function(res){return res.json()}).then(function(resp){var fr=(resp.results&&resp.results[0])?resp.results[0]:null;if(resp.success&&fr&&fr.success){setCardState(item,'done',fr.is_duplicate?'Linked':'Saved');if(fr.thumb_url){var img=item.querySelector('.mw-upload-thumb img');if(img){img.onload=function(){URL.revokeObjectURL(blobUrl)};img.src=fr.thumb_url}}
stats.active--;stats.succeeded++;zone.dispatchEvent(new CustomEvent('mediaUploaded',{detail:fr}))}else{var err=(fr&&fr.errors)?fr.errors.join(', '):'Upload failed';setCardState(item,'error',err);stats.active--;stats.failed++;zone.dispatchEvent(new CustomEvent('mediaError',{detail:{filename:file.name,errors:[err]}}))}
checkAllComplete(zone,stats)}).catch(function(){setCardState(item,'error','Network error');stats.active--;stats.failed++;checkAllComplete(zone,stats)})}
function compressForUpload(file){var MAX_DIM=1920;var QUALITY=0.85;if(typeof createImageBitmap!=='function'){return Promise.resolve(file)}
return createImageBitmap(file).then(function(bitmap){var w=bitmap.width;var h=bitmap.height;var max=Math.max(w,h);if(max<=MAX_DIM){bitmap.close();return file}
var scale=MAX_DIM/max;var canvas=document.createElement('canvas');canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise(function(resolve){canvas.toBlob(function(blob){if(!blob){resolve(file);return}
var name=file.name.replace(/\.[^.]+$/,'')+'.jpg';var compressed=new File([blob],name,{type:'image/jpeg',lastModified:file.lastModified||Date.now()});resolve(compressed)},'image/jpeg',QUALITY)})}).catch(function(){return file})}
function generatePreview(file,size){size=size||160;if(typeof createImageBitmap==='function'){return createImageBitmap(file,{resizeWidth:size,resizeHeight:size,resizeQuality:'medium'}).then(function(bitmap){var scale=Math.min(size/bitmap.width,size/bitmap.height,1);var canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise(function(resolve){canvas.toBlob(function(blob){resolve(blob?URL.createObjectURL(blob):URL.createObjectURL(file))},'image/jpeg',0.8)})}).catch(function(){return URL.createObjectURL(file)})}
return Promise.resolve(URL.createObjectURL(file))}
function escapeHtml(str){var d=document.createElement('div');d.textContent=str||'';return d.innerHTML}
function escapeAttr(str){return(str||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}
window.MowologyMediaUploader={init:init}})()